    // For arrays: values are the elements (all same type)
    // For lists: values are pairs of (object value, Type elementType)
    public static Dictionary<string, object> SaveCollection<T>(T collection) where T : class
    {
        var dict = new Dictionary<string, object>();

        if (collection is Array array)
        {
            // Arrays: just store each element with its index as key
            for (int i = 0; i < array.Length; i++)
