            {
                // Use a tuple or a custom object to hold value and type
                // Here we use a simple object with two properties
                dict[i.ToString()] = new { value = list[i], type = list.GetType() };
            }
        }
        else
        {
            // For non-array/list types (e.g., a single object), fallback to string representation
            // Or you could use reflection to serialize all fields, but for simplicity:
            dict[""] = collection.ToString();
        }

        return dict;
    }

