def highest_common_ancestor(root, node1, node2):
    """
    Finds the highest common ancestor (not lowest) of two nodes in a binary tree.
    Assumes node1 and node2 are present in the tree.
    """
    def helper(node):
        if not node:
            return None
        if node == node1 or node == node2:
            return node  # Current node is one of the targets
        left = helper(node.left)
        right = helper(node.right)
        if left and right:
            return node  # One in left subtree, one in right subtree
        return left or right  # At least one is in one of the subtrees

    return helper(root)

