def catalan_number(n):
    """
    Returns the nth Catalan number, which is the number of full binary trees with n vertices.
    """
    if n <= 0:
        return 0
    # C(n) = (2n choose n) // (n + 1)
    from math import comb
    return comb(2 * n, n) // (n + 1)

