    }
    .container {
      width: 100vw;
      height: 32px;
      display: flex;
      align-items: center;
      justify-content: center;
    }
    .pulse-line {
      position: absolute;
      left: 0; right: 0;
      top: 16px; /* center vertically */
      height: 1px;
      background: #ff5500;
      transform: translateX(0) scale(1);
    }
    .pulse-dot {
      position: absolute;
      left: 50%;
      top: 16px;
      width: 8px;
      height: 8px;
      background: #0ff;
      border-radius: 50%;
      transform: translateX(-50%) scaleY(1) rotate(0);
      transition: transform 0.15s cubic-bezier(.4,2,.6,1);
      will-change: transform;
    }
    .pulse-state {
      --pulse-height: 1.5; /* 1 (normal) to 1.5 (expanded) */
      --pulse-phase: 0; /* 0=normal, 1=rising, 2=falling */
    }
  </style>
</head>
<body>
  <div class="container">
    <div class="pulse-line"></div>
    <div class="pulse-dot" class="pulse-state"></div>
  </div>
  <script>
    const dot = document.querySelector('.pulse-dot');
    let pulseInterval = null;
    let pulsePhase = 0; // 0: normal, 1: rising, 2: falling
    let pulseTime = 2; // seconds per full cycle
    let pulseDelay = 0.5; // seconds to center (rise)
    let pulseDuration = 0.3; // seconds to peak

    function animatePulse() {
      // Reset phase for new cycle
      pulsePhase = 0;
      function step(t) {
        if (t >= pulseTime) {
          pulsePhase = 0;
          requestAnimationFrame(step);
          return;
        }
        let now = t / pulseTime;
        if (pulsePhase === 0) { // moving left to center
          if (now < pulseDelay) {
            // moving left
            dot.style.left = (50 - now * 100) + '%';
            dot.style.transform = `translateX(-50% + ${now*100}% ) scaleY(${1 + (now-pulseDelay)*1.4*(1-pulsePhase)})`;
            if (now < pulseDelay) dot.style.transform = `translateX(${(50 - now*100)}%) scaleY(1)`;
          } else if (now >= pulseDelay && now < pulseDelay + pulseDuration) {
            // rising pulse
            pulsePhase = 1;
            dot.style.transform = `translateX(${(50 - pulseDelay - (now-pulseDelay)*1.2)}%) scaleY(${1 + (now-pulseDelay-pulseDuration)*1.4})`;
          } else if (now >= pulseDelay + pulseDuration) {
            // moving right, falling
            pulsePhase = 2;
            let x = 50 + (now - (pulseDelay + pulseDuration)) * 1.2;
            dot.style.transform = `translateX(${x}% ) scaleY(${1 - (now - (pulseDelay + pulseDuration))*1.2})`;
          }
        } else if (pulsePhase === 1) { // rising peak at center
          if (now < pulseDelay + pulseDuration) {
            dot.style.transform = `translateX(50%) scaleY(${1.5 - (now - (pulseDelay + pulseDuration))*0.5})`;
          } else {
            // moving right down
            pulsePhase = 2;
            let t2 = now - (pulseDelay + pulseDuration);
            dot.style.transform = `translateX(${50 + t2*1.2}% ) scaleY(${1 - t2*0.5})`;
          }
        } else if (pulsePhase === 2) { // falling back
          let t2 = now - (pulseDelay + pulseDuration);
          dot.style.transform = `translateX(${50 - t2*1.2}% ) scaleY(${1 - t2*0.5})`;
        }
        requestAnimationFrame(step);
      }
      requestAnimationFrame(step);
    }

    // Start on page load
    if (pulseInterval) clearInterval(pulseInterval);
    pulseInterval = setInterval(animatePulse, 16); // ~60fps
    window.addEventListener('resize', () => {
      // Center on window resize
      const w = window.innerWidth;
      document.querySelector('.pulse-dot').style.left = (w/2 - 4) + 'px';
    });
  </script>
</body>
</html>
```

**How it works:**
- The red line is the "lead" (like an ECG baseline)
- The blue dot moves left to right, centered at the midpoint
- At the center, it expands vertically in a triangular shape (up then down) for a short duration, mimicking a heartbeat pulse
- No triangle is visible in the line itself—only the dot's height changes
- The effect is smooth and can be tuned by adjusting `pulseDuration`, `pulseDelay`, etc.

This is a realistic simulation of a medical device's waveform display using a combination of CSS for layout and JavaScript for the dynamic pulse logic.

